def related_block(slug):
    names = {s: n for s, n, _, _ in GUIDES}
    names.update({p["slug"]: p["name"] for p in PAGES})
    r = RELATED.get(slug)
    if not r:
        return ""
    return ('<h2 style="margin-top:36px">Related</h2><ul class="b">'
            + "".join(f'<li><a href="{s}.html">{e(names[s])}</a></li>' for s in r) + "</ul>")


