import datetime as _dt
for _r in CAL_ROWS:
    _d = _dt.date(2026, 11, 26) + _dt.timedelta(days=_r["day"] - 1)
    _r["post_date"] = _d.isoformat(); _r["weekday"] = _d.strftime("%a")


def write_calendar():
    d = OUT / "cal"
    d.mkdir(parents=True, exist_ok=True)
    (d / "gbp-365.json").write_text(json.dumps(CAL_ROWS, ensure_ascii=False), encoding="utf-8")
    cards = []
    for r in CAL_ROWS:
        cards.append(
            '<div class="c" data-m="%s" data-t="%s"><div class="h"><b>Day %d</b> · %s %s · <span>%s</span> · %s</div>'
            '<pre>%s</pre><div class="r"><b>Reel:</b> %s</div></div>' % (
                r["post_date"][:7], html.escape(r["topic"]), r["day"], r["weekday"], r["post_date"], html.escape(r["topic"]),
                html.escape(r["format"]), html.escape(r["caption"]), html.escape(r["reel_idea"])))
    months = sorted({r["post_date"][:7] for r in CAL_ROWS})
    topics = sorted({r["topic"] for r in CAL_ROWS})
    page = (
        '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
        '<meta name="robots" content="noindex,nofollow"><title>365-day Google post calendar</title><style>'
        'body{font-family:system-ui,sans-serif;margin:0;background:#f4f6f8;color:#1a2a3a}.w{max-width:760px;margin:auto;padding:12px}'
        '.c{background:#fff;border-radius:10px;padding:10px 12px;margin:10px 0;box-shadow:0 1px 3px rgba(0,0,0,.08)}.h{font-size:.85em;color:#456}.h span{color:#0a6;font-weight:600}'
        'pre{white-space:pre-wrap;font-family:inherit;font-size:.95em;margin:8px 0}.r{font-size:.85em;color:#555;border-top:1px dashed #ddd;padding-top:6px}'
        'select{font-size:1em;padding:6px;margin:4px 4px 4px 0}</style></head><body><div class="w"><h2>365-day Google post calendar</h2>'
        '<p>One post a day for Google Business Profile, with a reel idea. Nothing is posted until the doctor approves it in chat.</p>'
        '<select id="m"><option value="">All months</option>' + "".join('<option>%s</option>' % m for m in months) + '</select>'
        '<select id="t"><option value="">All topics</option>' + "".join('<option>%s</option>' % html.escape(t) for t in topics) + '</select>'
        '<div id="L">' + "".join(cards) + '</div></div><script>'
        "function f(){var m=document.getElementById('m').value,t=document.getElementById('t').value;"
        "Array.prototype.forEach.call(document.querySelectorAll('.c'),function(c){c.style.display=((!m||c.dataset.m==m)&&(!t||c.dataset.t==t))?'':'none'})}"
        "document.getElementById('m').onchange=f;document.getElementById('t').onchange=f;</script></body></html>")
    (d / "index.html").write_text(page, encoding="utf-8")


write_calendar()
